//! The cross-language BYTE PIN for the schedule renderers
//! (`DEC-BACKUP-RUST-OPS-001`): the golden files under
//! `docs/runbooks/backup-templates/` — the three plists AND the cron
//! fallback block (`backup-cron.golden`, the review-round MINOR-2 fold) —
//! are GENERATED by the Python `brutex/backup/schedule_render.py` and
//! golden-pinned byte-equal there (DEC-BACKUP-OFFBOX-001 §9); these tests
//! pin the Rust twins to the SAME literal bytes, so Rust == golden ==
//! Python holds by transitivity (the pytest side additionally pins
//! Rust == Python through the wheel).

use std::fs;
use std::path::PathBuf;

fn golden(name: &str) -> String {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../docs/runbooks/backup-templates")
        .join(name);
    fs::read_to_string(&path)
        .unwrap_or_else(|err| panic!("cannot read golden template {}: {err}", path.display()))
}

#[test]
fn backup_plist_matches_golden_bytes() {
    assert_eq!(
        brutex_ops::render_backup_plist(),
        golden("com.brutex.backup.plist")
    );
}

#[test]
fn deadman_plist_matches_golden_bytes() {
    assert_eq!(
        brutex_ops::render_deadman_plist(),
        golden("com.brutex.backup-deadman.plist")
    );
}

#[test]
fn drill_plist_matches_golden_bytes() {
    assert_eq!(
        brutex_ops::render_drill_plist(),
        golden("com.brutex.backup-drill.plist")
    );
}

#[test]
fn cron_lines_match_golden_bytes() {
    assert_eq!(
        brutex_ops::render_cron_lines(),
        golden("backup-cron.golden")
    );
}
